package com.exemplo.crud;

import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import java.util.List;

@RestController
@RequestMapping("/pessoas")
public class PessoaController {

    private final PessoaRepository repo;

    public PessoaController(PessoaRepository repo) {
        this.repo = repo;
    }

    @GetMapping
    public List<Pessoa> listar() {
        return repo.findAll();
    }

    @PostMapping
    public Pessoa cadastrar(@RequestBody Pessoa pessoa) {
        pessoa.setId(null);
        return repo.save(pessoa);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Pessoa> atualizar(
            @PathVariable Long id,
            @RequestBody Pessoa dados) {

        return repo.findById(id)
                .map(pessoa -> {
                    pessoa.setNome(dados.getNome());
                    return ResponseEntity.ok(repo.save(pessoa));
                })
                .orElse(ResponseEntity.notFound().build());
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deletar(@PathVariable Long id) {

        if (!repo.existsById(id)) {
            return ResponseEntity.notFound().build();
        }

        repo.deleteById(id);
        return ResponseEntity.noContent().build();
    }
}
