package com.exemplo.crud;

import jakarta.persistence.*;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@SpringBootApplication
@RestController
@RequestMapping("/pessoas")
public class App {

    private final PessoaRepo repo;

    public App(PessoaRepo repo) {
        this.repo = repo;
    }

    public static void main(String[] args) {

        SpringApplication.run(App.class, args);
    }

    @GetMapping
    public List<Pessoa> listar() {
        return repo.findAll();
    }

    @PostMapping
    public Pessoa criar(@RequestBody Pessoa p) {
        p.id = null;
        return repo.save(p);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Pessoa> atualizar(@PathVariable Long id, @RequestBody Pessoa dados) {
        return repo.findById(id).map(p -> {
            p.nome = dados.nome;
            return ResponseEntity.ok(repo.save(p));
        }).orElse(ResponseEntity.notFound().build());
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deletar(@PathVariable Long id) {
        if (!repo.existsById(id)) return ResponseEntity.notFound().build();
        repo.deleteById(id);
        return ResponseEntity.noContent().build();
    }
}

@Entity
class Pessoa {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    public Long id;
    public String nome;
}

interface PessoaRepo extends JpaRepository<Pessoa, Long> {}
