import fs from 'node:fs/promises';
import path from 'node:path';
import Database from 'better-sqlite3';

const DB = new Database('db.sqlite');
DB.exec(`CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL)`);
const stmt = {
  all: DB.prepare('SELECT id, name, email FROM users'),
  add: DB.prepare('INSERT INTO users (name, email) VALUES (?, ?)'),
  del: DB.prepare('DELETE FROM users WHERE id = ?')
};

const MIME = { '.html': 'text/html', '.mjs': 'text/javascript', '.css': 'text/css', '.ico': 'image/x-icon' };

http.createServer(async (req, res) => {
  // CSP Strict: inline scripts bloqueados, apenas 'self'
  res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self'; style-src 'self'");

  if (req.method === 'GET' && req.url === '/api/users') {
    return json(res, 200, stmt.all.all());
  }
  if (req.method === 'POST' && req.url === '/api/users') {
    const body = await parseBody(req);
    if (!body.name || !body.email) return json(res, 400, { error: 'Campos obrigatórios' });
    try { const info = stmt.add.run(body.name.trim(), body.email.trim().toLowerCase()); return json(res, 201, { id: info.lastInsertRowid, ...body }); }
    catch (e) { return json(res, 409, { error: 'Email já cadastrado' }); }
  }
  if (req.method === 'DELETE' && req.url?.startsWith('/api/users/')) {
    const id = Number(req.url.split('/').pop());
    const info = stmt.del.run(id);
    return info.changes ? json(res, 200, { ok: true }) : json(res, 404, { error: 'Não encontrado' });
  }

  // Static files
  let filePath = path.join('public', req.url === '/' ? 'index.html' : req.url);
  try {
    const content = await fs.readFile(filePath);
    res.writeHead(200, { 'Content-Type': MIME[path.extname(filePath)] || 'application/octet-stream' });
    res.end(content);
  } catch { res.writeHead(404); res.end('Not Found'); }
}).listen(3000, () => console.log('🚀 http://localhost:3000'));

