@Entity @Data @NoArgsConstructor @AllArgsConstructor
class Produto {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) Long id;
    @NotBlank(message = "Nome é obrigatório") String nome;
    @Positive(message = "Preço deve ser positivo") BigDecimal preco;
}

interface ProdutoRepository extends JpaRepository<Produto, Long> {}

@RestController @RequestMapping("/api/produtos") @RequiredArgsConstructor
class ProdutoController {
    private final ProdutoRepository repo;

    @GetMapping List<Produto> listarTodos() { return repo.findAll(); }

    @GetMapping("/{id}")
    Produto buscarPorId(@PathVariable Long id) {
        return repo.findById(id).orElseThrow(() -> new ResponseStatusException(NOT_FOUND, "Produto não encontrado"));
    }

    @PostMapping @ResponseStatus(CREATED)
    Produto criar(@Valid @RequestBody Produto produto) { return repo.save(produto); }

    @PutMapping("/{id}")
    Produto atualizar(@PathVariable Long id, @Valid @RequestBody Produto dados) {
        return repo.findById(id).map(p -> { p.setNome(dados.getNome()); p.setPreco(dados.getPreco()); return repo.save(p); })
                .orElseThrow(() -> new ResponseStatusException(NOT_FOUND, "Produto não encontrado"));
    }

    @DeleteMapping("/{id}") @ResponseStatus(NO_CONTENT)
    void deletar(@PathVariable Long id) {
        if (!repo.existsById(id)) throw new ResponseStatusException(NOT_FOUND, "Produto não encontrado");
        repo.deleteById(id);
    }
}
